निम्नलिखित C++ कोड का आउटपुट क्या होगा?
#include<iostream>
using namespace std;
long factorial(long a)
{
if (a > 1)
return (a * factorial(a + 1));
else
return(1);
}
int main()
{
long num = 3;
cout << num << "!=" << factorial(num);
return 0;
}

